"""Dependency-free static publication. Run from repository root."""
import json, html, re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public'
BASE='https://trailwise-gear.jaydenisraelruiz.workers.dev'
DATE='2026-10-26'
guides=json.loads((ROOT/'content/guides.json').read_text())
e=html.escape
def write(path,text):
    p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
def page(path,title,description,body,schema=None):
    url=BASE+('/' if path=='index.html' else '/'+path.replace('index.html',''))
    data={'@context':'https://schema.org','@type':'Organization','name':'Trailwise Gear','url':BASE} if schema is None else schema
    write(path,f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="google-site-verification" content="1MeKjoKHpi5pSPYf6qovnzJHeW9wuBDJeyeqPOC2RTk"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Trailwise Gear</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/images/ranger-woods-1280.webp"><meta name="theme-color" content="#183f35"><link rel="stylesheet" href="/style.css"><link rel="icon" href="/icon.svg" type="image/svg+xml"><script type="application/ld+json">{json.dumps(data)}</script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/" aria-label="Trailwise Gear home"><span class="mark" aria-hidden="true">△</span> TRAILWISE <span>GEAR</span></a><nav aria-label="Main navigation"><a href="/guides/">All guides</a><a href="/comparisons/">Compare gear</a><a href="/about/">About</a></nav></header><main id="main">{body}</main><footer><div><a class="brand" href="/">TRAILWISE GEAR</a><p>Go farther. Spend smarter.</p><p>From The Scenic Route: personal gear experience and clearly labeled research.</p></div><nav aria-label="Publication policies"><a href="/contact/">Contact & corrections</a><a href="/editorial-policy/">Editorial policy</a><a href="/affiliate-disclosure/">Affiliate disclosure</a><a href="/privacy/">Privacy</a><a href="/sitemap.xml">Sitemap</a></nav><p class="fine">© 2026 Trailwise Gear. Some guides include disclosed affiliate links; we may earn a commission on qualifying purchases. Conditions and equipment change; check current instructions before a trip.</p></footer><!-- Cloudflare Web Analytics --><script type='module' src='https://static.cloudflareinsights.com/beacon.min.js' data-cf-beacon='{{"token": "bf99e6384e404a42ab00d264a79358c6"}}'></script><!-- End Cloudflare Web Analytics --></body></html>''')
def inline(text):
    """Escape content, then render the small supported Markdown subset."""
    safe=e(text)
    def link(m):
        rel='sponsored external' if m[2].startswith(('https://bougerv.sjv.io/', 'https://www.dpbolvw.net/', 'https://www.tkqlhce.com/')) else 'external'
        return f'<a href="{m[2]}" rel="{rel}">{m[1]}</a>'
    safe=re.sub(r'\[([^\]]+)\]\((https://[^\s)]+)\)',link,safe)
    return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',safe)

def card(g):
    return f'<article class="card"><p class="eyebrow">{e(g["category"])}</p><h3><a href="/guides/{g["slug"]}/">{e(g["title"])}</a></h3><p>{e(g["description"])}</p><span class="fine">Research-based guide · Read guide →</span></article>'
def cards(items):return '<div class="grid">'+''.join(card(g) for g in items)+'</div>'
page('index.html','Real adventures. Gear worth bringing.','Gear and honest outdoor advice from the adventures behind The Scenic Route. Camping, truck gear, and research to help you get outside.',f'''<section class="hero hero-personal"><div class="hero-copy"><p class="eyebrow">FROM THE SCENIC ROUTE • INTO THE WILD</p><h1>Real Adventures.<br>Gear Worth Bringing.</h1><p class="lede">Hey, I'm Jayden, the creator behind The Scenic Route. I spend my free time exploring backroads, camping in the woods, and learning what gear actually makes a difference. This is where I share that gear, plus practical research to help you find your own setup.</p><div class="hero-actions"><a class="button" href="#quick-start">Get free camping tips →</a><a class="text-link" href="#featured-gear">See recommended gear →</a></div></div><div class="photo-panel photo-hero"><img src="/images/ranger-woods-1280.webp" srcset="/images/ranger-woods-640.webp 640w, /images/ranger-woods-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 50vw" width="1280" height="960" alt="My Ford Ranger parked among the trees on a woodland trail" fetchpriority="high" decoding="async"><span class="photo-label">THE SCENIC ROUTE / REAL TRAILS</span></div></section><div class="trust"><span>Made for real adventures</span><span>Field use labeled honestly</span><span>Affiliate links disclosed</span></div><section id="quick-start" class="quick-start" aria-labelledby="quick-start-title"><div class="section-head"><div><p class="eyebrow">FREE ADVICE FIRST</p><h2 id="quick-start-title">Start with a better plan, not a shopping list.</h2></div></div><p>Here from The Scenic Route? These free guides cover the basics before you spend a dollar. When you are ready, the gear picks just below give you a place to start.</p><div class="quick-links"><a href="/guides/first-car-camping-trip/">Free first camping trip checklist →</a><a href="/guides/budget-camping-gear-buying-order/">What to buy, borrow or skip →</a><a href="/guides/camping-power-bank-sizing/">Figure out how much camp power you need →</a></div></section><section id="featured-gear" aria-labelledby="featured-gear-title"><div class="section-head"><div><p class="eyebrow">GEAR I'D CONSIDER FOR THE NEXT TRIP</p><h2 id="featured-gear-title">Three useful places to start.</h2></div><a href="#my-gear">Browse more gear →</a></div><p class="fine"><strong>Affiliate disclosure:</strong> Shopping links may earn me a commission on qualifying purchases at no extra cost to you. I'll always distinguish gear I've used from gear I've researched.</p><div class="grid featured-grid"><article class="card"><p class="eyebrow">PERSONALLY USED · TRUCK LIGHTING</p><h3>Nilight LED light bars</h3><p>I've run a Nilight light bar on my Ranger for around two years. Read what I've learned before choosing the right size and mounting setup.</p><a href="/nilight-light-bar/">Read my experience →</a><a class="button" href="https://www.dpbolvw.net/click-101916053-17287346" target="_blank" rel="sponsored noopener noreferrer">Browse Nilight lights ↗</a></article><article class="card"><p class="eyebrow">RESEARCHED · CAMPING COMFORT</p><h3>Zenbivy sleep systems</h3><p>Compare quilts, pads and complete sleep setups for your kind of trip. These are researched options, not gear I've personally tested.</p><a href="/guides/foam-vs-inflatable-sleeping-pad/">Free sleeping pad guide →</a><a class="button" href="/zenbivy-sleep-gear/">Explore Zenbivy options →</a></article><article class="card"><p class="eyebrow">RESEARCHED · TRUCK UPGRADES</p><h3>KSP wheel spacers</h3><p>Considering a stance change? Check bolt pattern, hub fit and installation requirements before ordering. I haven't tested KSP products.</p><a href="#off-road-upgrades">Compare more truck upgrades →</a><a class="button" href="https://www.dpbolvw.net/click-101916053-17167892" target="_blank" rel="sponsored noopener noreferrer">Browse KSP spacers ↗</a></article></div></section><section id="my-gear"><div class="section-head"><div><p class="eyebrow">START EXPLORING</p><h2>Find gear for your next adventure.</h2></div></div><div class="experience-grid"><article class="experience-card"><div class="photo-panel photo-camp"><img src="/images/hammock-camp-1280.webp" srcset="/images/hammock-camp-640.webp 640w, /images/hammock-camp-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 33vw" width="1280" height="960" alt="Setting up my hammock at a wooded campsite" loading="lazy" decoding="async"></div><div class="experience-content"><p class="eyebrow">CAMPING & COMFORT</p><h3>My camping setup</h3><p>From hammock nights to cooking outdoors, start with practical basics that make camping easier.</p><a href="#camping-setup">Explore camping gear & guides →</a></div></article><article class="experience-card"><div class="photo-panel photo-truck"><img src="/images/muddy-tire-1280.webp" srcset="/images/muddy-tire-640.webp 640w, /images/muddy-tire-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 33vw" width="1280" height="960" alt="Mud on my Ranger tire after a trail drive" loading="lazy" decoding="async"></div><div class="experience-content"><p class="eyebrow">TRUCK & TRAIL</p><h3>My truck & trail gear</h3><p>Explore lighting, useful upgrades, and the decisions behind building a capable adventure setup.</p><a href="#truck-setup">Explore truck gear →</a></div></article><article class="experience-card"><div class="photo-panel photo-trail"><img src="/images/forest-trail-1280.webp" srcset="/images/forest-trail-640.webp 640w, /images/forest-trail-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 33vw" width="1280" height="960" alt="An autumn forest trail opening toward distant mountains" loading="lazy" decoding="async"></div><div class="experience-content"><p class="eyebrow">FIND YOUR WAY OUTSIDE</p><h3>Explore outdoor gear</h3><p>Research-backed comparisons and straightforward checklists for adventures that fit your budget.</p><a href="/comparisons/">Compare outdoor gear →</a></div></article></div></section><section id="camping-setup"><div class="section-head"><div><p class="eyebrow">MY CAMPING SETUP</p><h2>A simple camp. A better night outside.</h2></div></div><p>Hammock camping and cooking outdoors are part of my adventures. The guides below help you plan your own setup; they are researched advice, not reviews of the exact equipment in my photos.</p><div class="grid"><article class="card"><p class="eyebrow">CAMP ESSENTIALS · RESEARCHED</p><h3>Build your first camping kit</h3><p>Start with shelter, water and a workable plan before adding extras.</p><a href="/guides/first-car-camping-trip/">Plan a first camping trip →</a></article><article class="card"><p class="eyebrow">SLEEP EQUIPMENT · RESEARCHED</p><h3>Get your sleep system right</h3><p>Compare sleeping pads and explore Zenbivy quilts and sleep systems around your trip.</p><a href="/zenbivy-sleep-gear/">Explore sleep gear →</a><a href="/guides/foam-vs-inflatable-sleeping-pad/">Compare sleeping pads →</a></article><article class="card"><p class="eyebrow">CAMP COOKING · RESEARCHED</p><h3>Make room for a hot meal</h3><p>Compare stove systems, fuel and the complete cooking kit before you buy.</p><a href="/guides/pocketrocket-2-vs-jetboil-flash/">Compare camp stoves →</a></article></div></section><section class="story-strip"><div><p class="eyebrow">FROM MY ADVENTURES</p><h2>More trail time. Less guesswork.</h2><p>There's no perfect setup for everyone. I share things I've actually used alongside clearly labeled research and shopping options. You can enjoy the adventures without buying a thing.</p></div><a class="button light" href="/guides/">Explore the guidebook →</a></section><section id="guides"><p class="eyebrow">EXPLORE OUTDOOR GEAR · RESEARCHED</p><div class="section-head"><div><p class="eyebrow">PRACTICAL READING</p><h2>Plan well. Spend where it matters.</h2></div><a href="/guides/">Explore all 10 guides →</a></div>{cards(guides[:3])}</section><section class="feature"><p class="eyebrow">CAMP KITCHEN RESEARCH</p><h2>Sometimes the best upgrade is knowing what you don't need.</h2><p>Compare complete cooking systems before paying for a new stove or extra accessories.</p><a class="button light" href="/guides/pocketrocket-2-vs-jetboil-flash/">Compare camp stoves →</a></section><section id="truck-setup" class="owner-feature"><div class="owner-image"><img src="/images/ranger-woods-1280.webp" srcset="/images/ranger-woods-640.webp 640w, /images/ranger-woods-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 33vw" width="1280" height="960" alt="My Ranger on a wooded trail" loading="lazy" decoding="async"></div><div><p class="eyebrow">MY TRUCK &amp; TRAIL GEAR · PERSONALLY USED</p><h2>Two years on my Ranger. Still part of the setup.</h2><p>I've had a Nilight LED light bar on my Ford Ranger for approximately two years. Start with my ownership experience, then compare the current lighting options and mounting requirements for your truck.</p><p class="fine">Affiliate links: I may earn a commission on qualifying purchases, at no extra cost to you. My experience is with my own light bar, not every model in the store.</p><a class="button" href="/nilight-light-bar/">Read my Nilight experience →</a><p><a href="https://www.dpbolvw.net/click-101916053-17287346" target="_blank" rel="sponsored noopener noreferrer">Shop Nilight light bars ↗</a></p></div></section><section id="off-road-upgrades"><div class="section-head"><div><p class="eyebrow">BUDGET OFF-ROAD UPGRADES</p><h2>Research your next truck upgrade.</h2></div></div><p>Browse KSP Performance categories below. These are shopping options, not hands-on product reviews or confirmed fitment recommendations for any specific truck.</p><p class="fine"><strong>Affiliate disclosure:</strong> These are paid affiliate links. Trailwise Gear may earn a commission on qualifying purchases at no additional cost to you.</p><div class="grid"><article class="card"><p class="eyebrow">KSP Performance</p><h3>Wheel spacers</h3><p>Compare spacer dimensions, hub fit, hardware, and vehicle compatibility before ordering.</p><a href="https://www.dpbolvw.net/click-101916053-17167892" rel="sponsored noopener noreferrer" target="_blank">Browse wheel spacers →</a></article><article class="card"><p class="eyebrow">KSP Performance</p><h3>Leveling lift kits</h3><p>Research lift geometry, alignment needs, and vehicle-specific installation requirements.</p><a href="https://www.anrdoezrs.net/click-101916053-17167895" rel="sponsored noopener noreferrer" target="_blank">Browse leveling lift kits →</a></article><article class="card"><p class="eyebrow">KSP Performance</p><h3>Aluminum control arms</h3><p>Explore suspension component options; confirm exact fitment and intended use.</p><a href="https://www.jdoqocy.com/click-101916053-17167893" rel="sponsored noopener noreferrer" target="_blank">Browse aluminum control arms →</a></article><article class="card"><p class="eyebrow">KSP Performance</p><h3>Control arms</h3><p>Browse replacement and upgrade options matched to your vehicle.</p><a href="https://www.tkqlhce.com/click-101916053-17167894" rel="sponsored noopener noreferrer" target="_blank">Browse control arms →</a></article></div><p class="fine">Check vehicle year, drivetrain, bolt pattern, fitment, safety instructions, and seller specifications before purchasing. No KSP products have been independently tested by Trailwise Gear.</p></section><section id="portable-camp-power"><div class="section-head"><div><p class="eyebrow">CAMP POWER OPTIONS</p><h2>Explore portable power for your next campsite.</h2></div></div><p>ALLPOWERS offers portable power stations and solar charging options for drive-up camping and off-grid setups. Compare capacity in watt-hours, output ports, weight, charging methods and the power requirements of the devices you actually bring. A larger station may be unnecessary for a short trip.</p><p class="fine"><strong>Affiliate disclosure:</strong> The ALLPOWERS shopping links below are tracked affiliate links. Trailwise Gear may earn a commission on qualifying purchases at no additional cost to you.</p><div class="grid"><article class="card"><p class="eyebrow">ALLPOWERS · Official Store</p><h3>Browse the full US store</h3><p>Compare power stations and other solar power equipment, and confirm current prices, warranty and product specifications with the manufacturer. This is not a hands-on review.</p><a href="https://www.anrdoezrs.net/click-101916053-17222097" rel="sponsored noopener noreferrer" target="_blank">Shop ALLPOWERS →</a></article><article class="card"><p class="eyebrow">ALLPOWERS · Portable Power</p><h3>Portable power stations</h3><p>Compare battery capacities, output and charging options for your actual campsite needs before choosing a model.</p><a href="https://www.tkqlhce.com/click-101916053-17222100" rel="sponsored noopener noreferrer" target="_blank">Browse portable power stations →</a></article><article class="card"><p class="eyebrow">Trailwise Gear guide</p><h3>How much camp power do you need?</h3><p>Start with a watt-hour budget before investing in a portable power station.</p><a href="/guides/camping-power-bank-sizing/">Read our power sizing guide →</a></article></div><p class="fine">These product categories are for comparison; no ALLPOWERS products have been independently tested by Trailwise Gear.</p></section><section class="adventure-feature"><div><img src="/images/forest-trail-1280.webp" srcset="/images/forest-trail-640.webp 640w, /images/forest-trail-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 33vw" width="1280" height="960" alt="Fall colors along a forest trail with mountains in the distance" loading="lazy" decoding="async"></div><div><p class="eyebrow">FROM MY LATEST ADVENTURE</p><h2>The story starts on the trail.</h2><p>Follow The Scenic Route for backroads, camping, and the moments that make getting outside worth it. Catch the newest upload on the channel, then come back here to plan your own trip.</p><a class="button" href="https://www.youtube.com/@thescenicroute2026">Watch The Scenic Route ↗</a><p class="fine">The camping and truck guides here are related reading, not a verified equipment list for the latest video.</p><a href="/guides/first-car-camping-trip/">Plan your next overnight →</a></div></section><section class="about-strip"><p class="eyebrow">ABOUT THE SCENIC ROUTE</p><h2>Take the backroad. Make a story.</h2><p>I'm Jayden. I created The Scenic Route to share the adventures I make time for: exploring trails, camping in the woods, and heading out in my Ranger. Trailwise Gear is where that adventure continues after the video—a place to find my gear experience and research your own next step.</p><p>You will always see the difference between equipment I personally use and products I've only researched. The goal is to help you choose something useful for your trips.</p><a href="/about/">Meet Trailwise Gear →</a> · <a href="/editorial-policy/">How the guides are made →</a></section>''')
page('guides/index.html','Camping and trail guides','Browse practical camping, cooking, vehicle, and gear-buying guides.','<div class="page-intro"><p class="eyebrow">THE GUIDEBOOK</p><h1>A little planning goes a long way.</h1><p>Choose a real problem to solve, then find the equipment that fits.</p></div>'+cards(guides))
page('comparisons/index.html','Research-based gear comparisons','Compare complete systems and practical tradeoffs before buying outdoor gear.','<div class="page-intro"><p class="eyebrow">BEFORE YOU BUY</p><h1>Compare the tradeoffs.</h1><p>Research-based comparisons. No lab scores, purchased rankings, or claims of personal testing.</p></div>'+cards([g for g in guides if g['category']=='Gear comparisons']))
for g in guides:
    updated = g.get('updated')
    update_note = f' · Updated {e(updated)}' if updated else ''
    toc='<nav class="toc" aria-label="In this guide"><strong>In this guide</strong><ol>'+''.join(f'<li><a href="#section-{i}">{e(s[0])}</a></li>' for i,s in enumerate(g['sections']))+'</ol></nav>'
    body=f'<div class="article-head"><a href="/guides/">← All guides</a><p class="eyebrow">{e(g["category"])}</p><h1>{e(g["title"])}</h1><p class="lede">{e(g["description"])}</p><p class="fine">By Trailwise Gear editorial desk · Published and source-checked October 26, 2026 · Desk research{update_note}</p></div><div class="article-layout">{toc}<article class="prose"><aside class="answer"><strong>The practical answer</strong><p>{e(g["answer"])}</p></aside>'
    for i,(heading,text) in enumerate(g['sections']):
        body+=f'<section id="section-{i}"><h2>{e(heading)}</h2>'+''.join(f'<p>{inline(p)}</p>' for p in text.split('\n'))+'</section>'
    source_note = g.get("source_note", 'Manufacturer specifications and source guidance were checked on October 26, 2026. Buying recommendations are our editorial judgments. We have not tested these products.')
    body+='<section class="sources"><h2>Sources & evidence</h2><p>'+e(source_note)+'</p><ul>'+''.join(f'<li><a href="{e(url)}" rel="external">{e(label)}</a></li>' for label,url in g['sources'])+'</ul><p>Source references are ordinary links. Any commercial links are identified near the recommendation. <a href="/contact/">Report a correction</a>.</p></section></article></div><section><h2>Keep planning</h2>'+cards([next(x for x in guides if x['slug']==slug) for slug in g['related']])+'</section>'
    schema={'@context':'https://schema.org','@type':'Article','headline':g['title'],'description':g['description'],'datePublished':DATE,'dateModified':g.get('updated',DATE),'author':{'@type':'Organization','name':'Trailwise Gear editorial desk'},'publisher':{'@type':'Organization','name':'Trailwise Gear'},'mainEntityOfPage':BASE+'/guides/'+g['slug']+'/','citation':[s[1] for s in g['sources']]}
    page('guides/'+g['slug']+'/index.html',g['title'],g['description'],body,schema)
policies={
'about':('About Trailwise Gear','Practical outdoor information for people who care where their money goes.', [('Our purpose','I’m Jayden Ruiz, the creator behind The Scenic Route. I share trail drives, camping and outdoor adventures, and built Trailwise Gear as a place for viewers to continue exploring after a video. Trailwise Gear is an independent publication operated by me. We help budget-conscious campers and outdoor enthusiasts compare equipment, prepare for trips, and avoid buying gear that does not solve a real problem.'),('What you will find','Our initial publication focuses on beginner car camping, complete cooking systems, and conservative vehicle-trip preparation. The first ten guides are desk-researched. They do not represent field tests or professional assessments of your equipment.'),('How the business works','We may earn commissions through disclosed affiliate links, including BougeRV, Nilight, KSP Performance, ALLPOWERS and Zenbivy links on the homepage, in relevant guides and on our Zenbivy collection page. A commercial relationship does not mean that we tested a product. Editorial recommendations include borrowing, reusing equipment, and delaying purchases when those options fit the reader better.'),('Accountability','Sources and evidence limits appear in each guide. Readers can report factual errors through our contact page. See the editorial policy for our research, AI assistance, and correction practices.')]),
'contact':('Contact & corrections','Send a question or report a factual error.', [('Public contact method','Use the public GitHub issue tracker linked below for editorial questions, broken links, and corrections. A GitHub account is required. This is a public channel: do not include an address, phone number, payment information, account credentials, or other private details.'),('What to include','Include the article URL, the claim or link in question, and a reliable source when possible. For a gear question, include the model and the use case without personal information. We review reports when operating the publication; no response time is guaranteed.'),('Partnership inquiries','Brands may use the same public channel for non-confidential partnership inquiries. We do not accept payment for undisclosed recommendations or fabricated reviews. Do not send confidential contracts or tax information through an issue.')]),
'editorial-policy':('Editorial & review policy','How we research, label evidence, and correct mistakes.', [('Research-based vs hands-on','Every initial guide is desk-researched. Manufacturer statements are attributed and do not become our measured results. A future hands-on review must identify the product version, conditions, method, and limitations. We will not imply that we used a product when we have not.'),('Sources and recommendations','We prioritize manufacturer documentation for specifications and compatibility, public land managers for access guidance, and authoritative safety sources for safety claims. Prices and availability change; we do not publish invented prices or claim real-time stock. We compare complete systems and distinguish editorial judgment from verified facts.'),('AI assistance','AI tools assist with research, writing, development, and maintenance. This does not constitute hands-on product testing or independent expert certification. We check important factual claims against linked sources and do not invent customer reviews, lab results, credentials, or affiliate relationships.'),('Commercial independence','We plan to use affiliate links only after program approval and receipt of real tracking information. A relationship will be disclosed near relevant links. We do not sell positive conclusions. Borrowing and not buying remain legitimate recommendations. No products were supplied for the initial guides.'),('Corrections and updates','Report errors through the contact page. Material corrections will be recorded in the affected article, with an updated date. Dates change when substantive review occurs, not automatically to imply freshness. Safety instructions and local rules must always be checked again before use.')]),
'affiliate-disclosure':('Affiliate disclosure','Our current monetization status and intended disclosure practice.', [('Current status','As of November 5, 2026, Trailwise Gear includes disclosed BougeRV, Nilight, KSP Performance, ALLPOWERS and Zenbivy affiliate links on the homepage, in relevant guides and on the Zenbivy collection page. We may earn a commission on qualifying purchases through those links, at no additional cost to you. Ordinary manufacturer and reference links are not affiliate links unless identified as such. No earnings are claimed.'),('Future affiliate links','We label affiliate recommendations near their links and may earn commissions on qualifying purchases. We update this disclosure when adding relationships. We will also follow each program’s required wording and linking rules.'),('Your choices','You are free to use our guides without buying anything. We aim to recommend equipment based on fit, evidence, and total cost. Commercial relationships do not establish that a product was tested or that it is the best option for everyone.')]),
'privacy':('Privacy notice','A plain-language description of this site’s current data practices.', [('Scope and current features','This notice describes the Trailwise Gear static website prepared on October 26, 2026. The site uses Cloudflare Web Analytics to measure page views and visits. Cloudflare states that Web Analytics does not track individual visitors using cookies or local storage. The site does not include newsletter forms, account systems, payment collection, or embedded videos. We do not measure affiliate clicks with our own site event system. When you click a disclosed affiliate link, the relevant affiliate network (including Impact, CJ or AvantLink) and the merchant can process referral information and may use cookies or similar technology under their own policies to attribute qualifying purchases.'),('Hosting and technical data','The site is served by Cloudflare. Requests necessarily expose technical information such as IP addresses and browser request headers to the hosting provider. Cloudflare may process security, operational, and diagnostic data under its own policies. We have not verified the account’s logging or retention settings, so we do not promise that hosting logs are absent or retained for a particular period.'),('External links and contact','External websites apply their own privacy practices. Our public contact method uses GitHub; information posted in an issue is public and GitHub processes account and usage data under its own policies. Do not post private or sensitive information. We have no private contact form on this website.'),('Changes and questions','If we add analytics, forms, advertising, or affiliate tracking, we will review and update this notice to describe the actual implementation. Use the contact page for privacy questions without sharing sensitive details publicly.')])}
for slug,(title,desc,sections) in policies.items():
    body=f'<div class="page-intro"><p class="eyebrow">THE PUBLICATION</p><h1>{e(title)}</h1><p>{e(desc)}</p></div><article class="prose policy">'+''.join(f'<section><h2>{e(h)}</h2><p>{e(t)}</p></section>' for h,t in sections)
